const data = $input.first().json;

// Twilio envia: From, To, Body
const leadPhone = (data.From || '').replace(/\D/g, '');
const toNumber  = (data.To   || '').replace(/[^+\d]/g, '');
const message   = data.Body  || '';

// Detecta tipo de serviço pela mensagem
const msg = message.toLowerCase();
let serviceType = 'general';
if (msg.includes('clean') || msg.includes('maid') || msg.includes('housekeep')) {
  serviceType = 'cleaning';
} else if (msg.includes('construc') || msg.includes('remodel') || msg.includes('renovati')) {
  serviceType = 'construction';
} else if (msg.includes('install') || msg.includes('mount') || msg.includes('assembl')) {
  serviceType = 'installation';
}

return [{ json: {
  channel: 'sms',
  leadPhone,
  leadName: 'Customer',
  toNumber,
  message,
  serviceType,
  rawData: data
}}];

const email = $input.first().json;

const subject = email.subject || '';
const body    = email.text || email.snippet || '';
const toAddr  = email.to   || '';

// Extrai nome do lead do subject Thumbtack
// Ex: "John S. is interested in your services"
const nameMatch = subject.match(/^([A-Za-z]+(?:\s[A-Za-z]\.?)?)\s+is interested/) ||
                  body.match(/([A-Za-z]+(?:\s[A-Za-z]\.?)?)\s+sent you a message/);
const leadName = nameMatch ? nameMatch[1] : 'New Customer';

// Extrai número do lead se vier no body do email
const phoneMatch = body.match(/(?:\+?1[\s.-]?)?\(?([0-9]{3})\)?[\s.-]?([0-9]{3})[\s.-]?([0-9]{4})/);
const leadPhone = phoneMatch ? phoneMatch[0].replace(/\D/g,'') : null;

// Detecta serviço
const combined = (subject + ' ' + body).toLowerCase();
let serviceType = 'general';
if (combined.includes('clean') || combined.includes('maid')) {
  serviceType = 'cleaning';
} else if (combined.includes('construc') || combined.includes('remodel')) {
  serviceType = 'construction';
} else if (combined.includes('install') || combined.includes('mount')) {
  serviceType = 'installation';
}

return [{ json: {
  channel: 'thumbtack_email',
  leadPhone,
  leadName,
  toAddress: toAddr,
  message: body,
  serviceType,
  emailSubject: subject,
  rawData: email
}}];

